param([string]$Root=(Resolve-Path (Join-Path $PSScriptRoot "..")).Path,[string]$Output=(Join-Path $Root "docs/security/ISSUE_63_CLAIM_OCCURRENCE_INVENTORY.json")); $ErrorActionPreference="Stop"; $patterns=@(@{Term="knox";Id="CAP-001"},@{Term="certification";Id="CAP-002"},@{Term="certified";Id="CAP-002"},@{Term="compliance";Id="CAP-008"},@{Term="compliant";Id="CAP-008"},@{Term="attestation";Id="CAP-003"},@{Term="hardware backed";Id="CAP-006"},@{Term="trustzone";Id="CAP-006"},@{Term="secure enclave";Id="CAP-006"},@{Term="production ready";Id="CAP-007"},@{Term="carrier";Id="CAP-005"},@{Term="register";Id="CAP-005"},@{Term="firmware";Id="CAP-013"},@{Term="flashing";Id="CAP-012"},@{Term="flash";Id="CAP-012"},@{Term="bootloader";Id="CAP-012"},@{Term="unlock";Id="CAP-012"},@{Term="root";Id="CAP-012"},@{Term="rooting";Id="CAP-012"},@{Term="root access";Id="CAP-012"},@{Term="bypass";Id="CAP-012"},@{Term="fuse";Id="CAP-012"},@{Term="warranty";Id="CAP-012"},@{Term="recovery";Id="CAP-012"},@{Term="frp";Id="CAP-012"},@{Term="exploit";Id="CAP-012"},@{Term="quantum";Id="CAP-009"},@{Term="fips";Id="CAP-008"},@{Term="kyber";Id="CAP-009"},@{Term="dilithium";Id="CAP-009"},@{Term="tridar";Id="CAP-010"},@{Term="sentinel mesh";Id="CAP-011"}); $excluded=@(".git/","node_modules/","bin/","obj/","dist/","build/","out/","coverage/",".next/"); $binary=@(".png",".jpg",".jpeg",".gif",".ico",".zip",".7z",".dll",".exe",".pdb",".jar",".aar",".so",".woff",".woff2",".pdf"); $files=((& git -C $Root ls-files -z) -split "`0"|?{$_}); $occ=[System.Collections.Generic.List[object]]::new(); $ex=[System.Collections.Generic.List[object]]::new(); $n=0; foreach($file in $files){$norm=$file.Replace("\\","/");$ext=[IO.Path]::GetExtension($norm).ToLowerInvariant();if($norm -eq "docs/security/ISSUE_63_CLAIM_OCCURRENCE_INVENTORY.json"){$ex.Add([pscustomobject]@{file=$norm;reason="inventory-output"});continue};if(($excluded|?{$norm.StartsWith($_)}) -or ($binary -contains $ext)){ $ex.Add([pscustomobject]@{file=$norm;reason=if($binary -contains $ext){"binary-extension"}else{"excluded-directory"}});continue }; $full=Join-Path $Root $file; try{$text=[IO.File]::ReadAllText($full)}catch{ $ex.Add([pscustomobject]@{file=$norm;reason="unreadable"});continue };if($text.IndexOf([char]0) -ge 0){$ex.Add([pscustomobject]@{file=$norm;reason="binary-content"});continue};$lines=$text -split "`r?`n";for($i=0;$i -lt $lines.Count;$i++){ $window=(($lines[[Math]::Max(0,$i-1)..[Math]::Min($lines.Count-1,$i+1)])-join " ");$clean=[regex]::Replace($window.ToLowerInvariant(),"[^a-z0-9]+"," ").Trim();foreach($pat in $patterns){$needle=[regex]::Escape($pat.Term);if($clean -match "(^| )$needle[a-z0-9]*( |$)"){ $n++;$ctx=$lines[$i].Trim();if([string]::IsNullOrWhiteSpace($ctx)){$ctx=$window.Trim()};$class="implemented but unverified";$rationale="Automated occurrence disposition; human review required before any Verified claim.";if($norm -match "(^|/)tests?/|fixtures?/|assets?/" -or $ctx -match "(?i)fixture|mock|sample|fake|seed"){$class="test fixture";$rationale="Occurrence is located in or describes a test/fixture context."}elseif($norm -match "(^|/)docs/evidence/|archive-2026-08-17|reconciliation"){$class="historical evidence";$rationale="Occurrence is archive or reconciliation evidence, not a runtime claim."}elseif($norm -match "scripts/(validate-security-claims|test-security-claims)\.ps1"){$class="lint-rule definition";$rationale="Occurrence defines the claim-lint rule or test."}elseif($ctx -match "(?i)emulator|simulat|development only"){$class="simulator";$rationale="Occurrence explicitly describes emulation or development-only behavior."}elseif($ctx -match "(?i)planned|target|future|roadmap|experimental|not implemented|not available"){$class="planned";$rationale="Occurrence is explicitly future, experimental, or unavailable."}elseif($ctx -match "(?i)does not provide|unavailable|unsupported|prohibited|removed|disabled|not evidence|must not"){$class="prohibited/removed";$rationale="Occurrence explicitly limits or removes the capability."}elseif($pat.Term -in @("register","recovery","flash","firmware") -and $ctx -notmatch "(?i)claim|certif|security|device|operation|attest|boot|root|bypass"){$class="false positive";$rationale="Generic implementation term without a security-capability assertion."};$occ.Add([pscustomobject]@{occurrenceId=("OCC-{0:D6}" -f $n);file=$norm;line=($i+1);normalizedTerm=$pat.Term;context=$ctx;classification=$class;capabilityId=$pat.Id;evidenceRef=("docs/security/ISSUE_63_CAPABILITY_EVIDENCE_REGISTER.json#"+$pat.Id);rationale=$rationale;reviewStatus="pending-human-review"})}}}}; $doc=[pscustomobject]@{schemaVersion="1.0";issue=63;generatedAt=(Get-Date).ToUniversalTime().ToString("o");source="git ls-files tracked text files";includedFileCount=($files.Count-$ex.Count);occurrenceCount=$occ.Count;excludedFileCount=$ex.Count;exclusions=$ex;occurrences=$occ};$doc|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $Output -Encoding utf8;Write-Output ("generated occurrences="+$occ.Count+" exclusions="+$ex.Count+" files="+$files.Count)
